import React from "react";
class menuelement extends React.Component
{     render()
    {
        let menus=['home','aboutus','contactus'];
        return (
            <div>
                <ul>
                    <li>{menus[0]}</li>
                    <li>{menus[1]}</li>
                    <li>{menus[2]}</li>
                </ul>
            </div>
        )
    }

}
export default meuelement;
